PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE roster (   id       TEXT PRIMARY KEY,   initials TEXT NOT NULL,   name     TEXT NOT NULL,   role     TEXT NOT NULL,   meta     TEXT NOT NULL,   sort_order INTEGER );
CREATE TABLE announcements (   id    TEXT PRIMARY KEY,   title TEXT NOT NULL,   body  TEXT NOT NULL,   date  TEXT NOT NULL );
CREATE TABLE tournaments (   id     TEXT PRIMARY KEY,   name   TEXT NOT NULL,   date   TEXT NOT NULL,   format TEXT NOT NULL,   status TEXT NOT NULL );
CREATE TABLE applicants (   id      TEXT PRIMARY KEY,   ign     TEXT NOT NULL,   rank    TEXT NOT NULL,   discord TEXT NOT NULL,   notes   TEXT,   date    TEXT NOT NULL );
CREATE TABLE roster_members (     id INTEGER PRIMARY KEY AUTOINCREMENT,     role TEXT CHECK(role IN ('Leader', 'Admin', 'Officer', 'Member')) );
CREATE TABLE brackets (     id INTEGER PRIMARY KEY AUTOINCREMENT,     title TEXT NOT NULL,     bracket_data TEXT NOT NULL,     published_to_home INTEGER DEFAULT 0,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
DELETE FROM sqlite_sequence;
